<section class="content-width admin-layout"><form class="admin-create" action="/admin/tables/save" method="post" data-submit-label="Menyimpan…"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><h2>Tambah meja</h2><label for="table-code">Kode meja</label><input id="table-code" name="table_code" maxlength="20" placeholder="M-07" required><button class="btn btn-primary" type="submit">Tambah</button></form><div class="admin-list"><?php foreach ($tables as $table): ?><article><form action="/admin/tables/save" method="post"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $table['id'] ?>"><label>Kode meja</label><input name="table_code" value="<?= e($table['table_code']) ?>" maxlength="20" required><span><?= e(ucfirst($table['status'])) ?> · <?= (int) $table['total_visits'] ?> kunjungan historis</span><button class="btn btn-light" type="submit">Simpan</button></form><form action="/admin/tables/toggle" method="post"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $table['id'] ?>"><button class="admin-toggle" type="submit" <?= $table['status'] === 'occupied' ? 'disabled' : '' ?>><?= (int) $table['is_active'] === 1 ? 'Nonaktifkan' : 'Aktifkan' ?></button></form></article><?php endforeach; ?></div></section>
